//! Test corpus access for Rescyo tests and the Gate 1 runner.
//!
//! The corpus is generated by `cargo xtask corpus` (ADR-0002) into `corpus/out/` or the
//! directory in `RESCYO_CORPUS`. Damage is applied in memory by [`DamagedSource`], so one image
//! serves every corruption scenario without copies.
#![forbid(unsafe_code)]

use std::ops::Range;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use rescyo_io::{BlockSource, Geometry, ImageSource, ReadError, SourceIdentity};
use serde::Deserialize;

/// `expected.json` written by the corpus builder.
#[derive(Debug, Clone, Deserialize)]
pub struct Expected {
    pub format: u32,
    pub scenario: String,
    pub fs: String,
    pub table: String,
    pub image: String,
    pub image_size: u64,
    pub partition: Partition,
    pub layout: serde_json::Value,
    pub damage: std::collections::BTreeMap<String, [u64; 2]>,
    pub corruptions: Vec<String>,
    pub files: Vec<ExpectedFile>,
    pub dirs: Vec<ExpectedDir>,
}

#[derive(Debug, Clone, Copy, Deserialize)]
pub struct Partition {
    pub offset: u64,
    pub size: u64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ExpectedFile {
    pub path: String,
    pub size: u64,
    pub sha256: String,
    pub state: FileState,
    pub in_root: bool,
    pub fragmented: Option<bool>,
    pub mtime: i64,
    /// A named data stream (`file:stream`), not a file.
    #[serde(default)]
    pub stream: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FileState {
    Live,
    Deleted,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ExpectedDir {
    pub path: String,
    pub state: FileState,
}

/// One generated scenario on disk.
#[derive(Debug, Clone)]
pub struct Scenario {
    pub dir: PathBuf,
    pub expected: Expected,
}

impl Scenario {
    pub fn image_path(&self) -> PathBuf {
        self.dir.join(&self.expected.image)
    }

    /// Byte ranges zeroed by a corruption name such as `boot+fat1` (`none` = no damage).
    pub fn damage_ranges(&self, corruption: &str) -> Result<Vec<Range<u64>>, String> {
        if corruption == "none" {
            return Ok(Vec::new());
        }
        corruption
            .split('+')
            .map(|part| {
                self.expected
                    .damage
                    .get(part)
                    .map(|[a, b]| *a..*b)
                    .ok_or_else(|| format!("{}: unknown damage target {part:?}", self.expected.scenario))
            })
            .collect()
    }

    /// Opens the image with the named corruption applied in memory.
    pub fn open(&self, corruption: &str) -> Result<Arc<dyn BlockSource>, String> {
        let ranges = self.damage_ranges(corruption)?;
        let img = ImageSource::open(&self.image_path(), 512).map_err(|e| e.to_string())?;
        Ok(Arc::new(DamagedSource::new(img, ranges)))
    }
}

/// The corpus root: `$RESCYO_CORPUS`, else `<workspace>/corpus/out`.
pub fn corpus_root() -> PathBuf {
    if let Some(dir) = std::env::var_os("RESCYO_CORPUS") {
        return PathBuf::from(dir);
    }
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../corpus/out")
}

/// Loads every generated scenario, sorted by name. Empty if the corpus was not built.
pub fn scenarios() -> Vec<Scenario> {
    let Ok(entries) = std::fs::read_dir(corpus_root()) else {
        return Vec::new();
    };
    let mut out: Vec<Scenario> = entries
        .filter_map(Result::ok)
        .filter_map(|e| load(&e.path()).ok())
        .collect();
    out.sort_by(|a, b| a.expected.scenario.cmp(&b.expected.scenario));
    out
}

/// Loads one scenario directory.
pub fn load(dir: &Path) -> Result<Scenario, String> {
    let text = std::fs::read_to_string(dir.join("expected.json")).map_err(|e| e.to_string())?;
    let expected: Expected = serde_json::from_str(&text).map_err(|e| e.to_string())?;
    if expected.format != 1 {
        return Err(format!("unsupported expected.json format {}", expected.format));
    }
    Ok(Scenario {
        dir: dir.to_path_buf(),
        expected,
    })
}

/// A Source that reads zeros over the given byte ranges: corruption without copying images.
#[derive(Debug)]
pub struct DamagedSource<S> {
    inner: S,
    zeroed: Vec<Range<u64>>,
}

impl<S: BlockSource> DamagedSource<S> {
    pub fn new(inner: S, zeroed: Vec<Range<u64>>) -> Self {
        Self { inner, zeroed }
    }
}

impl<S: BlockSource> BlockSource for DamagedSource<S> {
    fn geometry(&self) -> Geometry {
        self.inner.geometry()
    }

    fn identity(&self) -> &SourceIdentity {
        self.inner.identity()
    }

    fn read_at(&self, offset: u64, buf: &mut [u8]) -> Result<(), ReadError> {
        self.inner.read_at(offset, buf)?;
        let end = offset + buf.len() as u64;
        for z in &self.zeroed {
            let lo = z.start.max(offset);
            let hi = z.end.min(end);
            if lo < hi {
                let a = usize::try_from(lo - offset).map_err(|_| ReadError::OutOfBounds)?;
                let b = usize::try_from(hi - offset).map_err(|_| ReadError::OutOfBounds)?;
                if let Some(part) = buf.get_mut(a..b) {
                    part.fill(0);
                }
            }
        }
        Ok(())
    }
}

/// Skips a test (by returning early) when the corpus has not been generated.
#[macro_export]
macro_rules! require_corpus {
    () => {{
        let s = $crate::scenarios();
        if s.is_empty() {
            eprintln!("skipped: corpus not generated (run `cargo xtask corpus`)");
            return;
        }
        s
    }};
}
